// 1. Validar Authorization: Bearer <SYNC_SECRET>
const firstItem = $input.first().json;
const headers = firstItem.headers || {};
const auth = headers.authorization || headers.Authorization || '';
const secret = ($env.SYNC_SECRET || '').trim();

if (!secret) {
  throw new Error('SYNC_SECRET no configurado en n8n');
}
if (!auth.startsWith('Bearer ') || auth.slice(7).trim() !== secret) {
  throw new Error('Unauthorized: Bearer token inválido');
}

// 2. Extraer y normalizar el body
let body = firstItem.body || firstItem;
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch (e) { throw new Error('JSON inválido en el body'); }
}

// Soporte para modelo individual por ID o URL
const rawModelId = body.modelId || body.model_id || body.id;
let singleModelId = null;
if (rawModelId) {
  singleModelId = String(rawModelId).trim();
} else if (body.url) {
  const match = String(body.url).match(/models\/(\d+)/i);
  if (match) singleModelId = match[1];
}

if (singleModelId) {
  return [{
    json: {
      singleModelId,
      categoria: body.categoria || body.category || 'Hogar & Decoración',
      meli_tipo_objeto: body.meli_tipo_objeto || '',
      forzarLicencia: body.forzarLicencia !== undefined ? Boolean(body.forzarLicencia) : true,
      busquedas_makerworld: [],
      limitPerConcept: 1
    }
  }];
}

const busquedas = Array.isArray(body.busquedas_makerworld)
  ? body.busquedas_makerworld
  : (Array.isArray(body) ? body : []);

if (busquedas.length === 0) {
  throw new Error('No se encontraron elementos en busquedas_makerworld ni modelId');
}

const limitPerConcept = Math.min(Math.max(Number(body.limitPerConcept) || 3, 1), 10);

return [{
  json: {
    busquedas_makerworld: busquedas,
    limitPerConcept
  }
}];

// PASO 1: Buscar candidatos en MakerWorld (vía FlareSolverr) y filtrar ESTRICTAMENTE licencias comerciales libres (sin suscripción/membresía).
const inputData = $input.first().json;
const busquedas = inputData.busquedas_makerworld || [];
const TOP_N = inputData.limitPerConcept || 3;
const FLARESOLVERR_URL = 'http://flaresolverr:8191/v1';

const LICENSE_MAP = {
  'BY': 'CC-BY',
  'BY-SA': 'CC-BY-SA',
  'BY-ND': 'CC-BY',
  'CC0': 'CC0',
  'BY-NC': 'CC-BY-NC',
  'BY-NC-SA': 'CC-BY-NC',
  'BY-NC-ND': 'CC-BY-NC',
};
const RESELLABLE_LICENSES = new Set(['CC-BY', 'CC-BY-SA', 'CC0']);

const TITLE_PATTERNS = [
  /\|?\s*(no |sin )?(ams|supports?|soportes?)\b/gi,
  /\|?\s*easy\s*(to\s*)?print(ing)?\b/gi,
  /\|?\s*no\s*supports?\b/gi,
  /\|?\s*免支撑\S*/g,
  /\|?\s*多色一盘\S*/g,
  /\|?\s*参数优化\S*/g,
  /\|?\s*模型优化\S*/g,
  /\|?\s*\d+\.\?d*mm\s*layer\b.*$/i,
  /\|?\s*\d+\s*walls?\b.*$/i,
  /\|?\s*\d+%\s*infill\b.*$/i,
];

function cleanTitle(t) {
  if (!t) return 'Sin título';
  let out = String(t);
  for (const p of TITLE_PATTERNS) out = out.replace(p, '');
  out = out.replace(/\s*[|·—–-]\s*$/g, '').replace(/\s{2,}/g, ' ').trim();
  return out.length >= 3 ? out : 'Sin título';
}

function stripHtml(html) {
  return String(html || '').replace(/<[^>]+>/g, ' ').replace(/\s{2,}/g, ' ').trim().slice(0, 2000);
}

let lastCookies = '';

async function flareGetJson(targetUrl, timeoutMs = 25000) {
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: FLARESOLVERR_URL,
    headers: { 'Content-Type': 'application/json' },
    body: {
      cmd: 'request.get',
      url: targetUrl,
      maxTimeout: timeoutMs
    },
    timeout: timeoutMs + 8000
  });
  const cookies = res?.solution?.cookies || [];
  if (cookies.length > 0) {
    lastCookies = cookies.map(c => `${c.name}=${c.value}`).join('; ');
  }
  const htmlStr = res?.solution?.response || '';
  const match = htmlStr.match(/<body[^>]*>(.*?)<\/body>/is);
  let rawJson = match ? match[1] : htmlStr;
  rawJson = rawJson.replace(/^<pre[^>]*>/i, '').replace(/<\/pre>.*$/is, '').replace(/<[^>]*>?/gm, '').trim();
  return JSON.parse(rawJson);
}

// MODO DIRECTO: Si viene singleModelId, consultar directamente su detalle
if (inputData.singleModelId) {
  const extId = String(inputData.singleModelId).trim();
  const directDetailUrl = `https://makerworld.com/api/v1/design-service/design/${extId}`;
  let directDet = null;
  try {
    directDet = await flareGetJson.call(this, directDetailUrl, 25000);
  } catch (err) {
    console.log(`Error consultando modelo directo ${extId}:`, err.message);
  }

  const rawLic = (directDet?.license || '').trim();
  let licType = LICENSE_MAP[rawLic];
  if (!licType || !RESELLABLE_LICENSES.has(licType)) {
    licType = 'custom';
  }
  const author = directDet?.designCreator?.name || 'Creador MakerWorld';
  const slug = directDet?.slug || extId;
  const coverImg = directDet?.cover || directDet?.coverLandscape || directDet?.coverPortrait ||
    (directDet?.designExtension?.design_pictures && directDet.designExtension.design_pictures[0]?.url) || null;

  const candidate = {
    externalId: extId,
    source: 'MAKERWORLD',
    sourceUrl: `https://makerworld.com/en/models/${slug}`,
    title: cleanTitle(directDet?.titleTranslated || directDet?.title || 'Modelo 3D'),
    description: stripHtml(directDet?.summaryTranslated || directDet?.summary || ''),
    imageUrl: coverImg,
    licenseType: licType,
    rawLicense: rawLic,
    licenseAttribution: `${author} — via MakerWorld`,
    category: inputData.categoria || 'Hogar & Decoración',
    tags: Array.isArray(directDet?.tags) ? directDet.tags.slice(0, 15) : ['3D Print', 'Bazar'],
    trendScore: Math.round(directDet?.likeCount || 0),
    provider: 'LOCAL',
    __cookies: lastCookies,
    __directDetail: directDet,
    __concepto: {
      id: 0,
      nombre_concepto: directDet?.title || 'Modelo Individual',
      categoria: inputData.categoria || 'Hogar & Decoración',
      meli_tipo: (inputData.meli_tipo_objeto || '').trim(),
      query_usada: `Direct ID: ${extId}`
    }
  };

  const report = {
    id: 0,
    nombre_concepto: candidate.title,
    categoria: candidate.category,
    query_principal: `Direct ID: ${extId}`,
    query_alternativa: '',
    usada_alternativa: false,
    seleccionados: 1,
    descartados_licencia: 0
  };

  return [{
    json: {
      ...candidate,
      __conceptReports: [report],
      __conceptsProcessed: 1
    }
  }];
}

// MODO LOTES (busquedas_makerworld)
const seenExternalIds = new Set();
const selectedCandidates = [];
const conceptReports = [];

for (const concepto of busquedas) {
  const cid = concepto.id ?? 0;
  const nombreConcepto = concepto.nombre_concepto || '';
  const categoriaSugerida = concepto.categoria || 'Gadgets & Utilidades';
  const q1 = (concepto.query_principal_ingles || '').trim();
  const q2 = (concepto.query_alternativa_ingles || '').trim();
  const meliTipo = (concepto.meli_tipo_objeto || '').trim();

  const conceptHits = [];
  let usedFallback = false;
  let discardedByLicense = 0;

  const processHits = (hits, queryUsed) => {
    for (const d of (hits || [])) {
      if (conceptHits.length >= TOP_N) break;
      const extId = String(d.id ?? '');
      if (!extId || seenExternalIds.has(extId)) continue;

      const rawLicense = (d.license || '').trim();
      const licenseType = LICENSE_MAP[rawLicense] || 'unknown';

      if (!RESELLABLE_LICENSES.has(licenseType)) {
        discardedByLicense++;
        continue;
      }

      seenExternalIds.add(extId);
      const author = d.designCreator?.name || 'Unknown';
      const slug = d.slug || extId;

      conceptHits.push({
        externalId: extId,
        source: 'MAKERWORLD',
        sourceUrl: `https://makerworld.com/en/models/${slug}`,
        title: cleanTitle(d.titleTranslated || d.title),
        description: '',
        imageUrl: d.cover || d.coverPortrait || null,
        licenseType,
        rawLicense,
        licenseAttribution: `${author} — via MakerWorld`,
        category: categoriaSugerida,
        tags: Array.isArray(d.tags) ? d.tags.slice(0, 15) : [],
        trendScore: Math.round(d.hotScore ?? d.likeCount ?? 0),
        provider: 'LOCAL',
        __cookies: lastCookies,
        __concepto: {
          id: cid,
          nombre_concepto: nombreConcepto,
          categoria: categoriaSugerida,
          meli_tipo: meliTipo,
          query_usada: queryUsed
        }
      });
    }
  };

  if (q1) {
    try {
      const searchUrl1 = `https://makerworld.com/api/v1/search-service/select/design2?orderBy=score&designType=0&isFromSearchList=false&limit=20&offset=0&licenses=BY,BY-SA,BY-ND,CC0&keyword=${encodeURIComponent(q1)}`;
      const parsed1 = await flareGetJson.call(this, searchUrl1, 25000);
      processHits(parsed1.hits || [], q1);
    } catch (e) {
      console.log(`Error buscando query principal "${q1}":`, e.message);
    }
  }

  if (conceptHits.length < TOP_N && q2) {
    usedFallback = true;
    try {
      const searchUrl2 = `https://makerworld.com/api/v1/search-service/select/design2?orderBy=score&designType=0&isFromSearchList=false&limit=20&offset=0&licenses=BY,BY-SA,BY-ND,CC0&keyword=${encodeURIComponent(q2)}`;
      const parsed2 = await flareGetJson.call(this, searchUrl2, 25000);
      processHits(parsed2.hits || [], q2);
    } catch (e) {
      console.log(`Error buscando query alternativa "${q2}":`, e.message);
    }
  }

  selectedCandidates.push(...conceptHits);
  conceptReports.push({
    id: cid,
    nombre_concepto: nombreConcepto,
    categoria: categoriaSugerida,
    meli_tipo_objeto: meliTipo,
    query_principal: q1,
    query_alternativa: q2,
    usada_alternativa: usedFallback,
    seleccionados: conceptHits.length,
    descartados_licencia: discardedByLicense
  });
}

if (selectedCandidates.length === 0) {
  return [{
    json: {
      __noCandidates: true,
      conceptReports,
      conceptsProcessed: busquedas.length
    }
  }];
}

return selectedCandidates.map((cand, idx) => ({
  json: {
    ...cand,
    __conceptReports: idx === 0 ? conceptReports : undefined,
    __conceptsProcessed: idx === 0 ? busquedas.length : undefined
  }
}));

// PASO 2 (Por cada producto individual): Detalle MakerWorld (FlareSolverr) + Cálculo de Precios + Gemini Multimodal + Copy FB
const cand = $input.first().json;
if (cand.__noCandidates) {
  return [{ json: cand }];
}

const GEMINI_API_KEY = ($env.GEMINI_API_KEY || '').trim();
const GEMINI_URL = `https://generativelanguage.googleapis.com/v1beta/models/gemini-flash-latest:generateContent?key=${GEMINI_API_KEY}`;
const FLARESOLVERR_URL = 'http://flaresolverr:8191/v1';
const flareUserAgent = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/125.0.0.0 Safari/537.36';

const TITLE_PATTERNS = [
  /\|?\s*(no |sin )?(ams|supports?|soportes?)\b/gi,
  /\|?\s*easy\s*(to\s*)?print(ing)?\b/gi,
  /\|?\s*no\s*supports?\b/gi,
  /\|?\s*免支撑\S*/g,
  /\|?\s*多色一盘\S*/g,
  /\|?\s*参数优化\S*/g,
  /\|?\s*模型优化\S*/g,
  /\|?\s*\d+\.\?d*mm\s*layer\b.*$/i,
  /\|?\s*\d+\s*walls?\b.*$/i,
  /\|?\s*\d+%\s*infill\b.*$/i,
];

function cleanVariantName(t, idx) {
  if (!t) return `Variante ${idx + 1}`;
  let raw = String(t).trim();
  let out = raw;
  for (const p of TITLE_PATTERNS) out = out.replace(p, '');
  out = out.replace(/\s*[|·—–-]\s*$/g, '').replace(/\s{2,}/g, ' ').trim();
  if (out.length >= 3) return out;
  const layerMatch = raw.match(/(\d+\.\?d*mm)/i);
  if (layerMatch) return `Capa ${layerMatch[1]}`;
  return `Variante ${idx + 1}`;
}

const FILAMENT_PRICE_PER_KG = 400, WASTE_PCT = 5, KWH_PRICE = 4.5, WATTS = 100, MARGIN_PCT = 400;
const MAINTENANCE_PER_HOUR = 500 / 1000;   // $0.50/h (refacciones $500 / 1000h)
const DEPRECIATION_PER_HOUR = 8000 / 5000; // $1.60/h (impresora $8000 / 5000h)

function priceForPlates(plates) {
  const grams = plates.reduce((s, p) => s + (Number(p.weight) || 0), 0);
  const seconds = plates.reduce((s, p) => s + (Number(p.prediction) || 0), 0);
  const hours = seconds / 3600;
  if (grams <= 0 || hours <= 0) return null;
  const effectiveGrams = grams * (1 + WASTE_PCT / 100);
  const filament = (effectiveGrams / 1000) * FILAMENT_PRICE_PER_KG;
  const electricity = hours * (WATTS / 1000) * KWH_PRICE;
  const maintenance = hours * MAINTENANCE_PER_HOUR;
  const depreciation = hours * DEPRECIATION_PER_HOUR;
  const subtotal = filament + electricity + maintenance + depreciation;
  return {
    grams: Number(grams.toFixed(1)),
    hours: Number(hours.toFixed(2)),
    price: Math.round(subtotal * (1 + MARGIN_PCT / 100))
  };
}

const stripHtml = (html) => String(html || '').replace(/<[^>]+>/g, ' ').replace(/\s{2,}/g, ' ').trim().slice(0, 2000);

let detJson = cand.__directDetail || {};
let lastCookies = cand.__cookies || '';
if (!detJson.instances || detJson.instances.length === 0) {
try {
  const detailUrl = `https://makerworld.com/api/v1/design-service/design/${cand.externalId}`;
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: FLARESOLVERR_URL,
    headers: { 'Content-Type': 'application/json' },
    body: { cmd: 'request.get', url: detailUrl, maxTimeout: 25000 },
    timeout: 32000
  });
  const cookies = res?.solution?.cookies || [];
  if (cookies.length > 0) {
    lastCookies = cookies.map(c => `${c.name}=${c.value}`).join('; ');
  }
  const htmlStr = res?.solution?.response || '';
  const match = htmlStr.match(/<body[^>]*>(.*?)<\/body>/is);
  let rawJson = match ? match[1] : htmlStr;
  rawJson = rawJson.replace(/^<pre[^>]*>/i, '').replace(/<\/pre>.*$/is, '').replace(/<[^>]*>?/gm, '').trim();
  detJson = JSON.parse(rawJson);
} catch (detErr) {
  console.log(`Error obteniendo detalle de ${cand.externalId}:`, detErr.message);
}
}

const instances = detJson?.instances || [];
const designExtension = detJson?.designExtension || {};
const designPics = Array.isArray(designExtension?.design_pictures)
  ? designExtension.design_pictures.map(p => p.url).filter(Boolean)
  : [];
const cover = detJson?.cover || detJson?.coverLandscape || detJson?.coverPortrait || (designPics && designPics[0]) || cand.imageUrl;
let images = cover ? [cover, ...designPics.filter(u => u !== cover)] : designPics;

const variantsRaw = instances.map((ins, i) => {
  const plates = (((ins.extention) || {}).modelInfo || {}).plates || [];
  const calc = priceForPlates(plates);
  if (!calc) return null;
  const insImg = (ins.extention && ins.extention.modelInfo && ins.extention.modelInfo.image) || ins.image || ins.cover || ins.picture;
  return {
    name: cleanVariantName(ins.title || ins.titleTranslated, i),
    grams: calc.grams,
    hours: calc.hours,
    price: calc.price,
    imageUrl: insImg || null
  };
}).filter(Boolean);

variantsRaw.forEach(v => {
  if (v.imageUrl && !images.includes(v.imageUrl)) {
    images.push(v.imageUrl);
  }
});

let variants = variantsRaw.sort((a, b) => a.price - b.price);
if (variants.length === 0) {
  variants = [{ name: 'Estándar', grams: 60, hours: 2.0, price: 145 }];
}

const priceFrom = variants[0].price;
const rawSummary = detJson?.summaryTranslated || detJson?.summary || '';

const p = {
  ...cand,
  description: stripHtml(rawSummary),
  descriptionHtml: rawSummary.slice(0, 2000),
  images: images.slice(0, 10),
  imageUrl: images[0] || cand.imageUrl,
  variants,
  priceFrom,
  price: priceFrom,
  meli_pictures: [],
  meli_variations: [],
  fb_post: '',
  __mainImgBase64: null,
  __mainImgMime: 'image/jpeg',
  __mainImgExt: 'jpg'
};

// Descargar imágenes (máx 2) para Gemini y Drive usando encoding: 'arraybuffer' para evitar corrupción UTF-8
const base64Images = [];
const imgUrls = p.images.length > 0 ? p.images : (p.imageUrl ? [p.imageUrl] : []);
for (let idx = 0; idx < Math.min(imgUrls.length, 6); idx++) {
  const u = imgUrls[idx];
  if (u) p.meli_pictures.push({ source: u });
}

for (let idx = 0; idx < Math.min(imgUrls.length, 3); idx++) {
  const imgUrl = imgUrls[idx];
  if (!imgUrl) continue;
  try {
    const rawBuf = await this.helpers.httpRequest({
      method: 'GET',
      url: imgUrl,
      encoding: 'arraybuffer',
      timeout: 8000,
      headers: {
        'User-Agent': flareUserAgent,
        'Accept': 'image/avif,image/webp,image/apng,image/svg+xml,image/*,*/*;q=0.8',
        'Referer': 'https://makerworld.com/',
        'Cookie': lastCookies
      }
    });
    const imgBuffer = Buffer.isBuffer(rawBuf) ? rawBuf : Buffer.from(rawBuf);
    if (imgBuffer && imgBuffer.length > 500) {
      let mimeType = null;
      let ext = 'jpg';
      const header = imgBuffer.slice(0, 4).toString('hex').toUpperCase();
      if (header.startsWith('89504E47')) { mimeType = 'image/png'; ext = 'png'; }
      else if (header.startsWith('52494646')) { mimeType = 'image/webp'; ext = 'webp'; }
      else if (header.startsWith('FFD8FF')) { mimeType = 'image/jpeg'; ext = 'jpg'; }
      else if (header.startsWith('47494638')) { mimeType = 'image/gif'; ext = 'gif'; }

      if (mimeType) {
        const b64Str = imgBuffer.toString('base64');
        if (!p.__mainImgBase64) {
          p.__mainImgBase64 = b64Str;
          p.__mainImgMime = mimeType;
          p.__mainImgExt = ext;
        }
        if (mimeType !== 'image/gif') {
          base64Images.push({ mimeType, data: b64Str });
        }
      }
    }
  } catch {}
}

// Enriquecimiento con Gemini
if (GEMINI_API_KEY) {
  const variantsInfo = p.variants.map((v, i) => `[${i + 1}] ${v.name} (${v.grams}g, $${v.price})`).join(', ');
  const prompt = `Analiza el siguiente producto para publicarlo en nuestra tienda "El Rincón de Brandy", en Mercado Libre y en redes sociales (Facebook/Instagram):
Concepto / Línea buscada: ${p.__concepto?.nombre_concepto || ''}
Categoría objetivo: ${p.__concepto?.categoria || ''}
Tipo de objeto para Mercado Libre: ${p.__concepto?.meli_tipo || 'no especificado'}
Título Original: ${p.title}
Descripción original: ${p.description?.slice(0, 500)}
Precio base: $${p.price} MXN
Variantes Físicas Disponibles (nombre, peso, precio): ${variantsInfo}

REGLA ESTRICTA DE IDIOMA ESPAÑOL:
REGLA ESTRICTA DE IDIOMA ESPAÑOL:
TODO (título comercial, descripción, nombres de variantes y hashtags) DEBE ESTAR 100% EN ESPAÑOL NEUTRO.
ESTRICTAMENTE PROHIBIDO dejar títulos, variantes o descripciones en inglés (como "Toy", "Fidget Toy", "Figure", "Frog", "Holder", "Stand", "Kit", "Case", etc.). Traduce y adapta el nombre al español comercial persuasivo para el cliente final en México.

REGLA CRÍTICA DE NEGOCIO:
Eres una tienda online que vende el producto FÍSICO ya fabricado. El cliente es un comprador normal (no sabe de impresión 3D).
ESTRICTAMENTE PROHIBIDO usar palabras como "impresión 3D", "print in place", "sin soportes", "STL", "filamento", "maker", "PLA", "Bambu", "A1 Mini", "AMS". Si una opción o modelo es de varios colores, utiliza ÚNICAMENTE el término "Multicolor" o "a todo color" (NUNCA utilices la palabra o sigla "AMS").
Adapta el título y la descripción al concepto comercial ("${p.__concepto?.nombre_concepto || ''}") destacando su beneficio práctico, diseño o funcionalidad.


REGLA OBLIGATORIA SOBRE VARIANTES Y COMPONENTES:
Si el modelo contiene piezas o perfiles que son partes separadas de un ensamble, juego o set (por ejemplo: un ajedrez con tablero por un lado y piezas por otro, una lámpara con base y pantalla, o una caja con tapa):
1. Es OBLIGATORIO que cada variante aclare con total precisión qué incluye y qué NO incluye en su "name" y en su "description" (ej. "Solo Piezas · Sin Tablero", "Solo Tablero · Sin Piezas"). Si una variante es de múltiples colores, nómbrala siempre "Multicolor" (PROHIBIDO usar la sigla "AMS").
2. En "description" de cada variante, detalla exactamente qué recibe el comprador (ej. "Incluye las 32 figuras de ajedrez. No incluye el tablero de juego" o "Incluye el juego completo listo para usar con tablero y todas sus piezas"). NUNCA vendas un componente suelto haciendo creer que es el producto completo.

REGLA SOBRE COMPONENTES ELECTRÓNICOS / ILUMINACIÓN:
Si el producto es una carcasa, lámpara o soporte que requiere LED/focos/electrónica externa, aclara brevemente en la descripción que incluye la estructura física lista para usar.
REGLA SOBRE DIMENSIONES Y MEDIDAS (Referencia Cama de Impresión Bambu Lab P1S 25.6 × 25.6 × 25.6 cm):
El cliente necesita saber el tamaño físico real aproximado de cada opción en centímetros (cm).
Toma en cuenta la escala máxima de la cama (25.6 cm) y el peso en gramos de cada variante:
1. En "dimensions" de cada variante, genera la medida estimada en formato: "~Largo × Ancho × Alto cm" o "~Diámetro cm" (ej. "~8.5 × 8.5 × 1.5 cm", "~22 × 22 × 1.8 cm", "~7.5 cm de alto").
2. En "size_label", pon una etiqueta corta y compacta para el botón (ej. "~8.5 cm", "~22 cm", "Rey ~7.5 cm").
NUNCA menciones gramos, filamento ni tecnología 3D en las medidas.

REGLA DE FOTO DE PORTADA PARA MERCADO LIBRE:
Mercado Libre sanciona y pausa publicaciones cuya foto de portada tenga textos superpuestos, marcas de agua, diagramas, letreros promocionales ("No supports", "Easy print", texto en inglés/chino) o logos.
Revisa las imágenes adjuntas en orden (Imagen 0, Imagen 1, Imagen 2 si existen):
