async function geminiJson(promptText) {
  if (!GEMINI_KEY) return null;
  try {
    const gRes = await this.helpers.httpRequest({
      method: 'POST',
      url: `https://generativelanguage.googleapis.com/v1beta/models/gemini-flash-latest:generateContent?key=${GEMINI_KEY}`,
      headers: { 'Content-Type': 'application/json' },
      body: {
        contents: [{ parts: [{ text: promptText }] }],
        generationConfig: { responseMimeType: 'application/json', temperature: 0.1 }
      },
      timeout: 15000
    });
    const gText = gRes?.candidates?.[0]?.content?.parts?.[0]?.text || '';
    const m = gText.match(/\{.*\}/s);
    return m ? JSON.parse(m[0]) : null;
  } catch (e) {
    return null;
  }
}

async function resolveMeliCategory(ctx) {
  const hints = [ctx.tipo, ctx.searchTerm, ctx.title, String(ctx.title || '').split(' ').slice(0, 3).join(' '), ctx.concepto, ctx.categoria]
    .map(cleanForSearch)
    .filter((q, idx, arr) => Boolean(q && q.length >= 3 && arr.indexOf(q) === idx));
  const textoClave = [ctx.tipo, ctx.searchTerm, ctx.title, ctx.concepto].filter(Boolean).join(' | ');

  // (a) Mapa curado: si coincide, no se consulta nada más
  const mapped = CATEGORY_MAP.find(c => isConfirmedId(c.id) && c.match.test(textoClave));
  if (mapped) {
    return { id: mapped.id, name: mapped.name, by: 'mapa', hints, candidates: [], discoveryAttrs: [] };
  }

  // (b) domain_discovery con todas las pistas
  const rawCandidateMap = new Map();
  for (const q of hints) {
    try {
      const discRes = await this.helpers.httpRequest({
        method: 'GET',
        url: `https://api.mercadolibre.com/sites/MLM/domain_discovery/search?q=${encodeURIComponent(q)}&limit=5`,
        headers: { 'User-Agent': 'Mozilla/5.0' },
        timeout: 6000
      });
      if (Array.isArray(discRes)) {
        for (const c of discRes) {
          if (c?.category_id && !FORBIDDEN_CAT_IDS.has(c.category_id) && !rawCandidateMap.has(c.category_id)) {
            rawCandidateMap.set(c.category_id, c);
          }
        }
      }
    } catch (discErr) {}
  }

  const validCandidates = [];
  for (const [cid, c] of rawCandidateMap.entries()) {
    try {
      const catDetail = await this.helpers.httpRequest({
        method: 'GET',
        url: `https://api.mercadolibre.com/categories/${cid}`,
        headers: { 'User-Agent': 'Mozilla/5.0' },
        timeout: 5000
      });
      if (!catDetail) continue;
      const isLeaf = !Array.isArray(catDetail.children_categories) || catDetail.children_categories.length === 0;
      const isAllowed = catDetail.settings?.listing_allowed !== false && catDetail.settings?.buying_allowed !== false;
      const fullBreadcrumb = (catDetail.path_from_root || []).map(p => p.name).join(' > ');
      const hasBadDomain = BAD_ROOTS.some(bad => fullBreadcrumb.toLowerCase().includes(bad));
      if (isLeaf && isAllowed && !hasBadDomain) {
        validCandidates.push({
          id: cid,
          name: catDetail.name || c.category_name || '',
          path: fullBreadcrumb,
          attrs: Array.isArray(c.attributes) ? c.attributes : []
        });
      }
    } catch (catErr) {}
  }

  const candidatePaths = validCandidates.map(vc => `[${vc.id}] ${vc.path}`);
  if (validCandidates.length === 0) {
    return { id: null, by: 'sin_candidatos', hints, candidates: [] };
  }
  if (!GEMINI_KEY) {
    const vc0 = validCandidates[0];
    return { id: vc0.id, name: vc0.name, by: 'discovery', hints, candidates: candidatePaths, discoveryAttrs: vc0.attrs };
  }

  // (c) Gemini elige entre los candidatos (o ninguno) y da su nivel de confianza
  let optionsPrompt = '0. NINGUNA de estas opciones describe con seguridad lo que el objeto ES físicamente\n';
  validCandidates.forEach((vc, idx) => {
    optionsPrompt += `${idx + 1}. [${vc.id}] ${vc.path}\n`;
  });

  const parsed = await geminiJson.call(this, `Eres experto en catalogación de Mercado Libre México.\nProducto: ${ctx.title}\nTipo de objeto: ${ctx.tipo || ctx.searchTerm || 'no especificado'}\nDescripción: ${String(ctx.description || '').slice(0, 400)}\nPistas: ${hints.join(' | ')}\n\nCandidatos encontrados en Mercado Libre:\n${optionsPrompt}\nReglas:\n- Elige según lo que el objeto ES físicamente, no según su tema o decoración. Ejemplos: una lámpara con forma de luna es una lámpara (no astronomía); un soporte de celular con forma de gato es un soporte (no una figura); una maceta con forma de dinosaurio es una maceta (no un juguete).\n- Si ninguna describe con seguridad el objeto, o son herramientas industriales, refacciones de vehículos o equipos especializados, elige 0.\n- "confianza": "alta" si la categoría es exactamente ese tipo de objeto, "media" si es cercana, "baja" si dudas.\n\nResponde ÚNICAMENTE un JSON válido con esta estructura:\n{\n  "index": 0,\n  "confianza": "alta"\n}`);

  if (!parsed) {
    return { id: null, by: 'gemini_error', hints, candidates: candidatePaths };
  }
  const chosenIdx = Number(parsed.index);
  const confianza = String(parsed.confianza || '').toLowerCase();
  if (!isNaN(chosenIdx) && chosenIdx > 0 && chosenIdx <= validCandidates.length && confianza !== 'baja') {
    const vc = validCandidates[chosenIdx - 1];
    return { id: vc.id, name: vc.name, by: `discovery+gemini (${confianza || 'sin dato'})`, hints, candidates: candidatePaths, discoveryAttrs: vc.attrs };
  }
  return { id: null, by: confianza === 'baja' ? 'gemini_confianza_baja' : 'gemini_ninguna', hints, candidates: candidatePaths };
}

async function resolveMeliAttributes(categoryId, categoryName, ctx, discoveryAttrs) {
  const attributesMap = new Map();
  attributesMap.set('BRAND', { id: 'BRAND', value_name: 'Genérica' });
  attributesMap.set('MODEL', { id: 'MODEL', value_name: ctx.modelName || 'Estándar' });
  for (const a of (discoveryAttrs || [])) {
    if (!a?.id || attributesMap.has(a.id)) continue;
    if (a.value_id) attributesMap.set(a.id, { id: a.id, value_id: a.value_id, value_name: a.value_name });
    else if (a.value_name) attributesMap.set(a.id, { id: a.id, value_name: a.value_name });
  }

  let catAttrs = [];
  try {
    const attrRes = await this.helpers.httpRequest({
      method: 'GET',
      url: `https://api.mercadolibre.com/categories/${categoryId}/attributes`,
      headers: { 'User-Agent': 'Mozilla/5.0' },
      timeout: 5000
    });
    if (Array.isArray(attrRes)) catAttrs = attrRes;
  } catch (attrErr) {}

  const pendingAttrs = catAttrs.filter(a => a?.tags?.required && !attributesMap.has(a.id));
  const fichaAttrs = pendingAttrs.map(a => ({
    id: a.id,
    nombre: a.name,
    tipo: a.value_type,
    valores: Array.isArray(a.values) && a.values.length > 0 ? a.values.map(v => v.name).slice(0, 40) : undefined,
    unidades: Array.isArray(a.allowed_units) && a.allowed_units.length > 0 ? a.allowed_units.map(u => u.name).slice(0, 10) : undefined
  }));

  const parsed = await geminiJson.call(this, `Eres experto en publicaciones de Mercado Libre México.\nProducto: ${ctx.title}\nTipo de objeto: ${ctx.tipo || ctx.searchTerm || 'no especificado'}\nDescripción: ${String(ctx.description || '').slice(0, 400)}\nMedidas aproximadas: ${ctx.dimensions || 'no especificadas'}\nOpción principal: ${ctx.modelName || 'Estándar'}\nCategoría elegida: ${categoryName}\n\nTareas:\n1. "meli_title": título estilo Mercado Libre, máx 58 caracteres: sustantivo principal del objeto + detalles clave. PROHIBIDO: impresión 3D, impreso, PLA, filamento, STL, micrómetro, micromedidor, calibrador, marcas.\n2. "attributes": llena CADA atributo de la lista para este objeto físico (material plástico, hecho artesanalmente, marca Genérica).\n   - Si el atributo trae "valores", copia EXACTAMENTE uno de esos valores.\n   - Si es numérico con unidad, responde número y unidad (ej. "12 cm"), estimando con las medidas.\n   - Si no se puede saber, usa el valor más neutro y honesto (ej. "Otro").\n\nAtributos a llenar:\n${JSON.stringify(fichaAttrs)}\n\nResponde ÚNICAMENTE un JSON válido con esta estructura:\n{\n  "meli_title": "Título máx 58 caracteres",\n  "attributes": [ { "id": "ID_DEL_ATRIBUTO", "value_name": "valor" } ]\n}`);

  let meliTitle = null;
  if (parsed?.meli_title) {
    meliTitle = String(parsed.meli_title).replace(/[^\p{L}\p{N}\s]/gu, ' ').replace(/\s{2,}/g, ' ').trim().slice(0, 58);
  }
  const aiVals = new Map();
  if (Array.isArray(parsed?.attributes)) {
    for (const av of parsed.attributes) {
      if (av?.id && av.value_name !== undefined && av.value_name !== null && String(av.value_name).trim()) {
        aiVals.set(String(av.id), String(av.value_name).trim());
      }
    }
  }

  const missing = [];
  for (const attr of pendingAttrs) {
    const vals = Array.isArray(attr.values) ? attr.values : [];
    const aiVal = aiVals.get(attr.id);
    if (vals.length > 0) {
      const exact = aiVal ? vals.find(v => String(v.name).toLowerCase() === aiVal.toLowerCase()) : null;
      const neutral = vals.find(v => /gen|otro|est|pl[aá]stico/i.test(v.name));
      const chosen = exact || neutral;
      if (chosen) attributesMap.set(attr.id, { id: attr.id, value_id: chosen.id, value_name: chosen.name });
      else missing.push(attr.id);
    } else if (aiVal) {
      attributesMap.set(attr.id, { id: attr.id, value_name: aiVal });
    } else if (attr.value_type === 'string') {
      attributesMap.set(attr.id, { id: attr.id, value_name: attr.id === 'MATERIAL' ? 'Plástico' : 'Estándar' });
    } else {
      missing.push(attr.id);
    }
  }

  return { attributes: Array.from(attributesMap.values()), meliTitle, missing };
}
