      tipo: prod.__concepto?.meli_tipo || '',
      searchTerm: prod.meli_search_term || '',
      concepto: prod.__concepto?.nombre_concepto || '',
      categoria: prod.category || '',
      modelName: firstVariantName,
      dimensions: (prod.variants && prod.variants[0]?.dimensions) || ''
    };

    // 1. Categoría (mapa -> discovery + Gemini). Sin categoría segura = no se publica.
    const cat = await resolveMeliCategory.call(this, ctx);
    if (!cat.id) {
      meliResults.push({
        externalId: prod.externalId,
        title: prod.title,
        status: 'pending_category',
        reason: cat.by,
        hints: cat.hints,
        candidates: cat.candidates,
        error: 'Sin categoría segura en Mercado Libre, no se publicó. Agrega este tipo de objeto al CATEGORY_MAP y vuelve a publicarlo.'
      });
      continue;
    }

    // 2. Atributos obligatorios + título ML
    const attrsRes = await resolveMeliAttributes.call(this, cat.id, cat.name, ctx, cat.discoveryAttrs);
    const finalMeliTitle = attrsRes.meliTitle || cleanMeliTitle.slice(0, 58);

    const meliPayload = {
      family_name: finalMeliTitle,
      category_id: cat.id,
      price: safeMeliPrice,
      currency_id: 'MXN',
      available_quantity: 5,
      buying_mode: 'buy_it_now',
      condition: 'new',
      listing_type_id: 'gold_special',
      pictures: picturesForMeli,
      attributes: attrsRes.attributes
    };

    try {
      const fullRes = await this.helpers.httpRequest({
        method: 'POST',
        url: 'https://api.mercadolibre.com/items',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${meliAccessToken}`
        },
        body: meliPayload,
        returnFullResponse: true,
        ignoreHttpStatusErrors: true,
        timeout: 20000
      });
      const statusCode = fullRes?.statusCode || 200;
      const mRes = fullRes?.body || fullRes;
      if (statusCode >= 200 && statusCode < 300 && mRes?.id) {
        prod.meliPermalink = mRes.permalink || null;
        meliResults.push({
          externalId: prod.externalId,
          title: prod.title,
          status: 'published',
          meliId: mRes.id,
          categoryId: cat.id,
          categoryName: cat.name,
          categoryBy: cat.by,
          permalink: mRes.permalink || null
        });
      } else {
        const causes = Array.isArray(mRes?.cause) ? mRes.cause.map(c => c.message || c.code).filter(Boolean).join(' | ') : '';
        const errMsg = causes || mRes?.message || mRes?.error || `HTTP ${statusCode}`;
        meliResults.push({
          externalId: prod.externalId,
          title: prod.title,
          status: 'error',
          categoryId: cat.id,
          categoryName: cat.name,
          categoryBy: cat.by,
          missingAttributes: attrsRes.missing,
          error: errMsg
        });
      }
    } catch (mErr) {
      let errDetail = mErr.message;
      try {
        const errBody = mErr.response?.data || mErr.response?.body || mErr.error || mErr.cause;
        if (errBody) errDetail = typeof errBody === 'string' ? errBody : JSON.stringify(errBody);
      } catch {}
      meliResults.push({
        externalId: prod.externalId,
        title: prod.title,
        status: 'error',
        categoryId: cat.id,
        categoryName: cat.name,
        categoryBy: cat.by,
        missingAttributes: attrsRes.missing,
        error: errDetail
      });
    }
  }
} else if (!meliAccessToken) {
  for (const prod of enrichedProducts) {
    meliResults.push({
      externalId: prod.externalId,
      title: prod.title,
      status: 'skipped_no_token',
      error: 'Token de Mercado Libre no disponible o expirado. Reconecta en /api/meli/auth'
    });
  }
}

// Preparar archivos para subir en lote a la carpeta de posts de Google Drive
const driveFilesToCreate = [];
for (const prod of enrichedProducts) {
  const safeSlug = prod.title
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-zA-Z0-9\s-]/g, '')
    .trim()
    .replace(/\s+/g, '_')
    .slice(0, 45) || `Producto_${prod.externalId}`;

  const baseName = `${prod.externalId}_${safeSlug}`;
  const directBazarUrl = `https://shongyi.com/bazar?p=${prod.externalId}`;
  const meliInfo = meliResults.find(r => r.externalId === prod.externalId);
  const meliLink = prod.meliPermalink || (meliInfo?.status === 'pending_category' ? 'Pendiente: revisar categoría de Mercado Libre' : 'En proceso / Ver catálogo');
  const txtContent = [
    `PRODUCTO: ${prod.title}`,
    `CONCEPTO: ${prod.__concepto?.nombre_concepto || ''}`,
    `CATEGORÍA: ${prod.category || ''}`,
    `PRECIO DESDE: $${prod.price} MXN`,
    `ENLACE DIRECTO AL PRODUCTO: ${directBazarUrl}`,
    `ENLACE MERCADO LIBRE: ${meliLink}`,
    `ENLACE MAKERWORLD ORIGINAL: ${prod.sourceUrl || ''}`,
    ``,
    `--- TEXTO DEL POST PARA FACEBOOK / INSTAGRAM ---`,
    prod.fb_post
  ].join('\n');

  driveFilesToCreate.push({
    externalId: prod.externalId,
    productTitle: prod.title,
    fileType: 'txt',
    fileName: `${baseName}_POST.txt`,
    mimeType: 'text/plain',
    base64Data: Buffer.from(txtContent, 'utf-8').toString('base64')
  });

  if (prod.__mainImgBase64) {
    driveFilesToCreate.push({
      externalId: prod.externalId,
      productTitle: prod.title,
      fileType: 'image',
      fileName: `${baseName}_IMAGEN.${prod.__mainImgExt || 'jpg'}`,
      mimeType: prod.__mainImgMime || 'image/jpeg',
      base64Data: prod.__mainImgBase64
    });
  }
}

return [{
  json: {
    success: true,
    summary: {
      conceptsProcessed,
      candidatesFound: enrichedProducts.length,
      enrichedCount: enrichedProducts.length,
      bazar: bazarSyncResult,
      meliConnected: Boolean(meliAccessToken),
      meliPublished: meliResults.filter(r => r.status === 'published').length,
      meliPendingCategory: meliResults.filter(r => r.status === 'pending_category').length,
      meliErrors: meliResults.filter(r => r.status !== 'published' && r.status !== 'pending_category').length,
      driveFilesPrepared: driveFilesToCreate.length
    },
    conceptReports,
    meliResults,
    driveFilesToCreate,
    products: enrichedProducts.map(p => ({
      externalId: p.externalId,
      title: p.title,
      description: p.description,
      category: p.category,
      price: p.price,
      licenseType: p.licenseType,
      imageUrl: p.imageUrl,
      sourceUrl: p.sourceUrl,
      variantsCount: (p.variants || []).length,
      concepto: p.__concepto?.nombre_concepto,
      fb_post: p.fb_post
    }))
  }
}];

const first = $input.first().json;
const files = first.driveFilesToCreate || [];

if (files.length === 0) {
  return [{ json: { __skipDrive: true } }];
}

return files.map(f => ({
  json: {
    __skipDrive: false,
    externalId: f.externalId,
    productTitle: f.productTitle,
    fileType: f.fileType,
    fileName: f.fileName
  },
  binary: {
    data: {
      data: f.base64Data,
      mimeType: f.mimeType,
      fileName: f.fileName
    }
  }
}));

const base = $('3. Publicar en Bazar y Mercado Libre').first().json;
const driveItems = $input.all().map(i => i.json).filter(x => x && x.id && !x.__skipDrive);

const { driveFilesToCreate, ...cleanBase } = base;
cleanBase.summary.driveUploadedCount = driveItems.length;
cleanBase.summary.driveFolderId = '1YQMXeP7h3s53_8RxPs4C7lAK4XxwU_Do';
cleanBase.summary.driveFolderUrl = 'https://drive.google.com/drive/folders/1YQMXeP7h3s53_8RxPs4C7lAK4XxwU_Do';
cleanBase.driveFiles = driveItems.map(d => ({
  id: d.id,
  name: d.name,
  mimeType: d.mimeType,
  webViewLink: d.webViewLink || `https://drive.google.com/file/d/${d.id}/view`
}));

return [{ json: cleanBase }];
